const $=s=>document.querySelector(s);const pins=['32440059823576911','140596819604566401','137782069843506170','754141900117278005','752804893948611846'];$('#source-links').innerHTML=pins.map((p,i)=>`<a href="https://www.pinterest.com/pin/${p}/" target="_blank" rel="noreferrer">Photo ${i+1} ↗</a>`).join('');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let clerk=null,ready=false,user=null,admin=false,filter='upcoming',attendance=[],activities=[];
const date=new Date();date.setDate(date.getDate()+5);date.setHours(18,0,0,0);const sample=(id,title,description,location,days)=>({id,title,description,location,starts_at:new Date(+date+days*86400000).toISOString(),ends_at:new Date(+date+days*86400000+7200000).toISOString()});
const examples=[sample('demo-1','An evening with the brotherhood','An evening to reconnect, share a meal, and spend time with the circle.','Location to be announced',0),sample('demo-2','Purpose in action','Come together for a shared community initiative. Details will follow.','Location to be announced',7),sample('demo-3','The monthly circle','Conversations, new ideas, and the next chapter for Eros.','Location to be announced',14)];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
function notice(title,text){$('#notice-title').textContent=title;$('#notice-text').textContent=text;$('#auth-widget').replaceChildren();if(!$('#notice').open)$('#notice').showModal()}
$('.close').onclick=()=>$('#notice').close();$('#notice').addEventListener('click',e=>{if(e.target===$('#notice'))$('#notice').close()});
async function api(action,body){const token=clerk?.session?await clerk.session.getToken():null;const r=await fetch('/api/portal?action='+action,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed. Please try again.');return d}
async function login(){if(!ready){notice('Member access is being prepared.','Clerk sign-in has not been configured for this preview. Member records and attendance will become available after the Eros Clerk keys and database are connected.');return}if(user){document.getElementById('member').scrollIntoView();return}clerk.openSignIn()}
document.querySelectorAll('[data-login]').forEach(b=>b.onclick=login);
function render(){const list=activities.filter(a=>filter==='all'||filter==='attended'?filter!=='attended'||attendance.some(r=>r.activity_id===a.id):new Date(a.ends_at)>=new Date());$('#activity-list').innerHTML=list.map(a=>{const d=new Date(a.starts_at),checked=attendance.some(r=>r.activity_id===a.id);return `<article class="event"><div class="event-date">${d.toLocaleDateString('en',{month:'short'}).toUpperCase()}<strong>${d.getDate()}</strong></div><div><span class="eyebrow">${a.id.startsWith('demo-')?'EXAMPLE GATHERING':'BROTHERHOOD GATHERING'}</span><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><p class="meta">${esc(d.toLocaleString('en-PH',{weekday:'short',hour:'numeric',minute:'2-digit',month:'short',day:'numeric'}))} · ${esc(a.location)}</p></div><button data-check="${esc(a.id)}" ${checked?'disabled':''}>${checked?'✓ Attendance recorded':'Check in ↗'}</button></article>`}).join('')||'<p class="muted" style="padding:35px 0">'+(filter==='attended'?(user?'No attendance recorded yet.':'Sign in to see your attendance.'):'No activities announced yet. Check back soon.')+'</p>';document.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{if(!user)return login();if(b.dataset.check.startsWith('demo-'))return toast('This is an illustrative gathering. An admin must publish a real activity first.');b.disabled=true;try{await api('checkin',{activityId:b.dataset.check});await refresh();toast('Your attendance has been recorded.')}catch(e){toast(e.message);b.disabled=false}})}
async function refresh(){try{const d=await api('activities');activities=d.activities;if(user){const m=await api('me');attendance=m.attendance;admin=m.admin;$('#member-name').textContent=user.fullName||user.firstName||'Eros member';$('#member-status').textContent=attendance.length+' gatherings attended';$('#member-actions').innerHTML='<button class="text-button" id="signout">Sign out ↗</button>';$('#signout').onclick=async()=>{try{await api('session',{event:'sign_out'})}catch{}await clerk.signOut();location.reload()};$('[data-login]').textContent='My circle ↗';$('#admin').hidden=!admin;if(admin)await loadAdmin()}render()}catch(e){toast(e.message)}}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});$('#admin-link').onclick=()=>{if(!user)return login();if(!admin)return notice('Administrator access required.','Your signed-in account has no administrator role. Contact the Eros administrator.');$('#admin').scrollIntoView()};
async function loadAdmin(){const d=await api('admin');$('#metrics').innerHTML=[['Activities',d.activities],['Check-ins',d.attendance.length],['Members',d.members]].map(([l,n])=>`<div class="metric"><strong>${n}</strong><span class="muted">${l}</span></div>`).join('');$('#audit').innerHTML=d.logs.map(r=>`<div class="audit-row">${esc(r.name)} · ${esc(r.event)}<small>${esc(r.details)} · ${esc(new Date(r.created_at).toLocaleString())}</small></div>`).join('')||'<p class="muted">No member activity yet.</p>';window.exportRecords=d.attendance}
$('#create-activity').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=Object.fromEntries(f);b.starts=new Date(b.starts).toISOString();b.ends=new Date(b.ends).toISOString();if(b.ends<=b.starts)return toast('End time must be after the start time.');const button=e.target.querySelector('button');button.disabled=true;try{await api('create',b);e.target.reset();await refresh();toast('Activity published.')}catch(e){toast(e.message)}finally{button.disabled=false}};
$('#export').onclick=()=>{const rows=[['Member','Activity','Checked in'],...(window.exportRecords||[]).map(r=>[r.name,r.title,r.checked_at])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='eros-attendance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
async function boot(){try{const c=await api('config');if(c.publishableKey){const host=atob(c.publishableKey.split('_').slice(2).join('_')).replace(/\$$/,'');const script=document.createElement('script');script.src='https://'+host+'/npm/@clerk/clerk-js@5/dist/clerk.browser.js';script.dataset.clerkPublishableKey=c.publishableKey;script.crossOrigin='anonymous';await new Promise((resolve,reject)=>{script.onload=resolve;script.onerror=reject;document.head.append(script)});clerk=window.Clerk;await clerk.load();ready=true;user=clerk.user;clerk.addListener(async state=>{if(state.user?.id!==user?.id){user=state.user;await refresh();if(user)api('session',{event:'sign_in'}).catch(()=>{})}});if(user)await api('session',{event:'sign_in'});await refresh();$('#activity-state').textContent='THE EROS SCHEDULE';return}}catch{}activities=examples;render()}
boot();
